import{_ as s,C as i,o as t,c as r,a2 as a,b as h,w as n,a as d,E as l,a8 as c}from"./chunks/framework.DTMisvi0.js";const _=JSON.parse('{"title":"Accounts","description":"","frontmatter":{},"headers":[],"relativePath":"docs/accounts.md","filePath":"docs/accounts.md"}'),g={name:"docs/accounts.md"};function u(p,e,m,f,b,w){const o=i("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h1><p>What a guest gets by signing up, and what the server and the phones do with an <strong>account</strong>. This is the spec for <a href="https://github.com/tkint/coach-poulpy/issues/25" target="_blank" rel="noreferrer">#25</a>; the tickets built from it are its sub-issues. How a request is authenticated is in <a href="./the-api">The API</a> and <a href="./adr/0020-every-credential-resolves-to-one-caller">ADR 0020</a>; the phone stays the source of truth (<a href="./adr/0001-local-first-phone-is-the-source-of-truth">ADR 0001</a>).</p><h2 id="signing-up-and-signing-in" tabindex="-1">Signing up and signing in <a class="header-anchor" href="#signing-up-and-signing-in" aria-label="Permalink to &quot;Signing up and signing in&quot;">​</a></h2><ul><li><strong>Email and password only, for now.</strong> Sign in with Apple and Google come later, each as one new authenticator; no route changes. Passwords are hashed with Argon2id.</li><li><strong>The email is confirmed before any data leaves the phone.</strong> Signing up sends a link; until it is tapped, the phone keeps working as a guest and uploads nothing. A typo in the address can never tie health data to someone else&#39;s mailbox.</li><li><strong>Health data consent is asked at sign-up</strong>, with a link to what is stored and why.</li><li><strong>Forgotten password</strong>: the person asks for a reset link by email and chooses a new password; every phone is signed out.</li><li><strong>Mail goes out over plain SMTP</strong> to an EU provider set in the server&#39;s settings, so the provider can change without a code change.</li></ul><h2 id="the-phone-and-the-account" tabindex="-1">The phone and the account <a class="header-anchor" href="#the-phone-and-the-account" aria-label="Permalink to &quot;The phone and the account&quot;">​</a></h2>',5)),(t(),h(c,null,{default:n(()=>[l(o,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20guest(%5B%22Guest%22%5D)%20--%20%22sign%20up%22%20--%3E%20pending%5B%22Account%2C%20email%20not%20confirmed%3Cbr%2F%3Ephone%20still%20a%20guest%22%5D%0A%20%20%20%20pending%20--%20%22tap%20the%20link%22%20--%3E%20synced%5B%22Signed%20in%3Cbr%2F%3Ephone%20uploads%2C%20then%20syncs%22%5D%0A%20%20%20%20guest%20--%20%22sign%20in%20to%20an%20existing%20account%22%20--%3E%20merged%5B%22Signed%20in%3Cbr%2F%3Eguest%20data%20merged%20into%20the%20account%22%5D%0A%20%20%20%20synced%20--%20%22sign%20out%22%20--%3E%20cleared(%5B%22Empty%20guest%22%5D)%0A%20%20%20%20merged%20--%20%22sign%20out%22%20--%3E%20cleared%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<ul><li><strong>The first upload keeps every id</strong> (<a href="./adr/0005-ids-are-uuidv7-made-on-the-device">ADR 0005</a>).</li><li><strong>Signing in on a phone that has guest data merges it</strong> into the account. Ids never collide and sync keeps both edits (<a href="./adr/0006-sync-keeps-both-edits">ADR 0006</a>), so nothing is lost or overwritten.</li><li><strong>Signing out clears the phone once everything is uploaded.</strong> If some changes can&#39;t be uploaded (no connection), the phone says so and lets the person wait or sign out anyway. The phone then starts again as an empty guest, so the next person on a shared phone sees nothing.</li></ul><h2 id="what-follows-the-account" tabindex="-1">What follows the account <a class="header-anchor" href="#what-follows-the-account" aria-label="Permalink to &quot;What follows the account&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Follows the account</th><th>Stays on each phone</th></tr></thead><tbody><tr><td>Workouts, plans, enrollments, sessions</td><td>Theme</td></tr><tr><td>Profile and body log</td><td>App icon</td></tr><tr><td>Units and language</td><td>Paired treadmills and other devices</td></tr></tbody></table><h2 id="leaving" tabindex="-1">Leaving <a class="header-anchor" href="#leaving" aria-label="Permalink to &quot;Leaving&quot;">​</a></h2><ul><li><strong>Deleting the account happens at once</strong>, after the password: every row is deleted, every phone is signed out and goes back to a guest with its own copy, and the nightly dumps age out within 30 days.</li><li><strong>Export</strong> gives all the account&#39;s data as JSON, and sessions as FIT files.</li></ul><h2 id="not-yet" tabindex="-1">Not yet <a class="header-anchor" href="#not-yet" aria-label="Permalink to &quot;Not yet&quot;">​</a></h2><p>Apple and Google sign-in, the website&#39;s sign-in, sharing and coaching, and personal access tokens (<a href="https://github.com/tkint/coach-poulpy/issues/228" target="_blank" rel="noreferrer">#228</a>).</p>',7))])}const k=s(g,[["render",u]]);export{_ as __pageData,k as default};
